"""Deep expansion, batch E: Replit and Lovable tutorials."""
from coursekit import ill_flow, ill_cycle, ill_quad, ill_stack
from expand import extend
from exp_a import tb
from exp_d import NOTE

SECURITY = tb(["Check", "Why", "How"], [
    ["Secrets never in code or chat", "Keys in prompts or repos leak and get abused", "Use the Secrets panel or environment variables; rotate any key you pasted by mistake"],
    ["Authentication and roles", "Anyone with the link could see private data", "Require login for private pages; check roles on the server, not only in the UI"],
    ["Input validation", "Bad input causes errors and attacks", "Validate types and lengths; escape output; use parameterised queries"],
    ["Row-level or per-user data rules", "Users must only see their own data", "Define rules in the database; test with two accounts"],
    ["Rate limits and abuse control", "Bots can run up costs", "Limit sign-ups, form posts and AI calls; add CAPTCHA if needed"],
    ["Payment handling", "Card data is regulated", "Use a hosted checkout (for example Razorpay, Stripe); never store card numbers"],
    ["Privacy and consent", "Personal data laws apply (DPDP Act)", "Collect minimum data, show a privacy notice, allow deletion"],
    ["Backups and recovery", "Mistakes and bad deploys happen", "Use checkpoints, version control and database backups; test a restore"]])

# =====================================================================  REPLIT
def replit(C):
    deep = {
     0: r"""<h3>Workspace map</h3>""" + tb(["Area", "What it is for"], [["Agent / chat panel", "Describe what you want; the Agent plans, writes code, installs packages and fixes errors"], ["File tree and editor", "See and edit the code; read what the Agent changed"], ["Preview / webview", "The running app, in a browser frame"], ["Shell / console", "Run commands and see logs"], ["Secrets", "Store keys and passwords securely as environment variables"], ["Database and storage tools", "Built-in database and file storage options (check current names)"], ["Version control / Git", "Commits, branches, GitHub link"], ["Deployments", "Publish the app to a public URL"]]) + NOTE,
     1: r"""<h3>A mini-PRD prompt that works</h3><pre>Build a leave-request web app for a 30-person company.
Users: Employee (submit, see status), Manager (approve or reject), HR (see all, export CSV).
Pages: Login, My requests, New request, Team requests (manager), Admin (HR).
Data: users(name, email, role), requests(user, type, start, end, reason, status).
Rules: end date after start; managers see only their team; email on decision.
Style: clean, mobile-friendly, blue accent.
Start with the data model and the employee flow only. Ask me before adding anything else.</pre><p>Ask the Agent to <b>plan first</b>, review the plan, then let it build in small steps, checking the preview after each step.</p>""",
     2: r"""<h3>Where each kind of data goes</h3>""" + tb(["Data", "Where"], [["API keys, passwords", "Secrets (environment variables)"], ["Users, records, orders", "Database (SQL such as PostgreSQL for structured data)"], ["Uploaded files and images", "Object storage"], ["Small settings", "Config file or database table"], ["Temporary cache", "In memory or a cache service"]]),
     3: r"""<h3>Deployment types (confirm current options)</h3>""" + tb(["Type", "Good for"], [["Static", "Landing pages, portfolios; no server code"], ["Autoscale", "Web apps and APIs with variable traffic; pay for usage"], ["Reserved VM", "Always-on services, bots, long processes"], ["Scheduled", "Jobs that run on a timetable (daily report, cleanup)"]]),
     5: r"""<h3>Cost watch-list</h3><ul><li>Agent usage can be billed by work done; keep prompts focused and stop loops.</li><li>Deployments and databases may have separate charges.</li><li>Set budgets or alerts if available and review usage weekly.</li></ul>""",
    }
    new = [
     ("intermediate", "Prompting the Agent like a product manager", "Write specs, checkpoints and reviews that get reliable results.", ill_flow(["Write a mini-PRD", "Ask for a plan", "Approve the plan", "Build one slice", "Test in the preview", "Checkpoint and continue"], "A reliable Agent workflow") + r"""
<ul><li><b>Describe outcomes and rules, not code:</b> users, pages, data, rules, edge cases, visuals.</li><li><b>Slice the work:</b> authentication, then data model, then main flow, then polish. Large vague prompts create tangled apps.</li><li><b>Give examples:</b> sample records, example emails, screenshots.</li><li><b>Say what must not change:</b> 'Do not change the login page'.</li><li><b>Debugging prompt:</b> 'When I click Submit on the New Request page, nothing happens. The console shows [error]. Find the cause, explain it, then fix it.'</li><li><b>Use checkpoints:</b> restore if the Agent breaks something; commit working versions to Git.</li><li><b>Ask for explanations:</b> 'Summarise what you changed and any risks.'</li></ul>""" + tb(["Weak prompt", "Strong prompt"], [["Make a nice dashboard", "Create a dashboard with 3 cards (open requests, approved this month, average response time) and a table of requests with filters by status and date"], ["Fix the bug", "Describe steps, expected vs actual result, error text, and what changed just before"], ["Add payments", "Add a Razorpay hosted checkout for the Pro plan at Rs 799, store the payment ID, and mark the user as Pro only after the webhook confirms"]]),
      ["Slice the work and review each slice.", "Write rules and edge cases in the prompt.", "Use checkpoints and Git for safety."], "Write a mini-PRD prompt and a debugging prompt for an app idea of your own."),
     ("intermediate", "Three practical builds: internal tool, landing page with leads, and an API or bot", "Build examples PMs actually need.", r"""
<h3>Build 1: Internal request tracker</h3><ol><li>Prompt the data model (requests, users, roles).</li><li>Add login and roles (employee, manager).</li><li>Build the form, list and approval flow.</li><li>Add email or Slack notification via a secret key.</li><li>Test with two accounts; deploy as Autoscale.</li></ol>
<h3>Build 2: Landing page with waitlist</h3><ol><li>Create a one-page site with hero, features, FAQ and sign-up form.</li><li>Store sign-ups in the database; prevent duplicates by email.</li><li>Send a confirmation email; add a privacy notice and consent checkbox.</li><li>Add analytics events (page view, sign-up).</li><li>Deploy as Static or Autoscale; connect a custom domain.</li></ol>
<h3>Build 3: Small API or bot</h3><ol><li>Define endpoints (for example GET /status, POST /order).</li><li>Add authentication via an API key in Secrets.</li><li>Log requests; add rate limiting.</li><li>Deploy on a reserved VM if it must stay always on (for example a Telegram or WhatsApp-style bot using the provider's API).</li></ol>""" + tb(["Prototype goal", "What 'good enough' means"], [["Validate an idea with 10 users", "Works for happy path, basic login, real data, clear failure messages"], ["Internal tool for a team", "Secure login, backups, error alerts, owner assigned"], ["Demo to stakeholders", "Polished main flow, sample data"]]),
      ["Pick builds that match the goal.", "Add auth, validation and notifications deliberately.", "Define 'good enough' before building."], "Build one of the three apps and write a list of what is missing for production."),
     ("intermediate", "Data, authentication and integrations in detail", "Design the data and logins properly.", tb(["Topic", "Guidance"], [["Data model", "List entities (users, orders), fields and relationships; ask the Agent to create tables and migrations; avoid changing structures casually once real data exists"], ["Authentication", "Use a built-in or well-known auth service; support password reset; consider login with Google; never build your own crypto"], ["Authorisation", "Check roles and ownership on the server for every request"], ["Environment separation", "Use separate databases or keys for testing and production"], ["Integrations", "Use official SDKs and API keys in Secrets; handle errors and rate limits; verify webhooks (signatures)"], ["Email and notifications", "Use a transactional email provider; test with a sandbox"], ["Payments", "Use hosted checkout and webhooks; do not trust the browser alone to say a payment succeeded"], ["Files", "Limit types and sizes; scan or restrict public access"]]) + r"""
<div class="box"><b>Migration tip:</b> before changing a database structure with real data, ask the Agent to write a migration, test it on a copy, and keep a backup.</div>""",
      ["Model data first; protect it with auth and roles.", "Separate test and production.", "Confirm payments server-side."], "Draw the data model and roles for an app idea, then prompt the Agent to implement only that."),
     ("advanced", "Quality, security and performance checklist", "Make your app safe enough to share.", SECURITY + r"""
<h3>Quality and performance</h3><ul><li><b>Testing:</b> ask the Agent to write tests for key flows; run them before deploying; test on a phone.</li><li><b>Error handling:</b> friendly messages, logs, alerts for failures.</li><li><b>Performance:</b> avoid loading everything at once; paginate lists; compress images; check load time on 4G.</li><li><b>Accessibility:</b> labels, contrast, keyboard use.</li><li><b>Observability:</b> view logs and add basic analytics and uptime checks.</li></ul>""",
      ["Security basics are mandatory before sharing.", "Test with two users and on a phone.", "Log errors and watch costs."], "Run the checklist on one of your apps and fix the top five findings."),
     ("advanced", "Git, collaboration, environments and handing over to engineers", "Work with developers and move beyond a prototype.", r"""
<ul><li><b>Git and GitHub:</b> commit often; use branches for risky changes; connect to a GitHub repository so engineers can review and extend.</li><li><b>Collaboration:</b> invite teammates; agree who prompts the Agent to avoid conflicting changes.</li><li><b>Environments:</b> development, staging, production with separate keys and data.</li><li><b>Handoff package:</b> repository link, README (purpose, how to run), environment variable list (names only), data model diagram, known issues, security review notes and next steps.</li><li><b>When to hand off:</b> real customers, payments, personal data, scale, compliance needs or complex integrations.</li></ul>""" + tb(["Stage", "Owner", "Output"], [["Idea and prototype", "PM using Agent", "Working prototype and learnings"], ["Hardening", "Engineer", "Tests, security, performance, monitoring"], ["Production", "Engineering team", "Scalable, supported system"]]),
      ["Use Git from day one.", "Prepare a handoff package.", "Know when to graduate to engineering."], "Write the README and handoff list for a Replit app you built."),
     ("advanced", "When to use Replit vs Lovable vs other tools, and PM use cases", "Choose the right builder.", tb(["Need", "Replit", "Lovable", "No-code (Zapier / Make)", "Engineers"], [["Quick web app prototype", "Good", "Excellent for UI-first apps", "Not for UI", "Slower"], ["Backend logic, APIs, bots", "Strong", "Possible with Supabase / functions", "Workflows only", "Strong"], ["Polished front-end", "Good", "Excellent", "No", "Strong"], ["Automation between apps", "Possible", "Limited", "Excellent", "Possible"], ["Production-grade scale and compliance", "Hand off", "Hand off", "Limited", "Best"]]) + r"""
<h3>PM use cases</h3><ul><li>Prototype to test a concept with real users before asking for engineering time.</li><li>Internal tools: approvals, trackers, dashboards.</li><li>Data explorations and small scripts.</li><li>Demos for stakeholders and investors.</li><li>Learning technical constraints by building.</li></ul>""",
      ["Match the tool to the job.", "Prototypes validate; engineers productionise.", "Use building to learn constraints."], "Pick a feature idea and decide which tool you would use and why."),
    ]
    qa = [("What is Replit Agent best used for?", "Turning a clear description into a working app quickly: prototypes, internal tools and small services, with a human reviewing and testing."),
          ("How do you write a good prompt for an AI app builder?", "Describe users, pages, data, rules and edge cases, work in small slices, give examples, say what must not change, and ask for a plan before building."),
          ("How do you keep secrets safe?", "Store them in Secrets or environment variables, never in code, prompts or repositories, and rotate any key that was exposed."),
          ("What are the deployment options and when to use them?", "Static for simple sites, Autoscale for apps with variable traffic, Reserved VM for always-on services, and Scheduled for timed jobs (confirm current options)."),
          ("What security checks matter before sharing an AI-built app?", "Secrets, authentication and roles, validation, per-user data rules, rate limits, safe payments, privacy and backups."),
          ("When should you hand an AI-built app to engineers?", "When it has real customers, payments, personal data, scale or compliance needs, or when logic and integrations become complex."),
          ("How do you control costs when building with an Agent?", "Keep prompts focused, work in slices, stop loops, watch usage and budgets, and avoid unnecessary rebuilds."),
          ("How do you debug with an Agent?", "Give steps, expected and actual results and error messages, ask for the cause and an explanation before the fix, and test again.")]
    gl = [("Agent", "AI that plans and writes code for you"), ("Checkpoint", "A saved state you can restore"), ("Secrets", "Secure storage for keys and passwords"), ("Autoscale", "Deployment that adjusts to traffic"), ("Reserved VM", "Dedicated always-on server"),
          ("Migration", "A controlled change to the database structure"), ("Webhook", "A call from another service when an event occurs"), ("Staging", "A test copy of production")]
    cheat = [("Prompt shape", "Users, pages, data, rules, edge cases, slice"), ("Safe by default", "Secrets, auth, validation, backups"), ("Handoff", "Repo, README, env names, data model, risks")]
    return extend(C, deep, new, qa, gl, cheat, links=[("OWASP Top 10 (web security)", "https://owasp.org/www-project-top-ten/"), ("Razorpay docs", "https://razorpay.com/docs/")])

# =====================================================================  LOVABLE
def lovable(C):
    deep = {
     0: r"""<h3>Lovable at a glance</h3>""" + tb(["Part", "Role"], [["Chat / prompt panel", "Describe changes; ask questions in chat mode and build in agent mode (names may vary)"], ["Live preview", "See and click the app; use visual edit tools for small text and style changes"], ["Code view and GitHub", "Inspect and sync the code to a repository"], ["Supabase integration", "Database, authentication, storage and server functions"], ["Project knowledge", "Instructions and context that the AI keeps in mind (brand rules, constraints)"], ["Publish and domains", "Deploy to a public URL and connect a custom domain"], ["Security scan", "Automated checks for common issues (confirm current features)"]]) + NOTE,
     1: r"""<h3>Prompt formula: ROLE, GOAL, SCREENS, DATA, RULES, STYLE</h3><pre>You are building a clinic appointment app.
Goal: patients book a 15-minute slot with a doctor and get a confirmation.
Screens: Home, Doctor list, Doctor detail with calendar, Booking form, My bookings, Admin (doctors, slots).
Data: doctors(name, speciality, fee), slots(doctor, start, status), bookings(patient, slot, status).
Rules: no double booking; patients see only their bookings; admins manage slots.
Style: calm green, large text, mobile first, English and Hindi labels.</pre><ul><li>Start with <b>layout and mock data</b>, then connect real data.</li><li>One feature per prompt; test; then move on.</li><li>Use <b>screenshots or sketches</b> for layout and say 'keep everything else unchanged'.</li></ul>""",
     2: r"""<h3>Supabase concepts in plain words</h3>""" + tb(["Concept", "Meaning"], [["Tables", "Where records live (like spreadsheets)"], ["Authentication", "Sign-up, login, password reset, social login"], ["Row Level Security (RLS)", "Rules that decide which rows each user may read or change"], ["Policies", "The actual RLS rules, for example 'a user can see rows where user_id equals their ID'"], ["Storage", "Buckets for files and images"], ["Edge Functions", "Small server-side code for secrets, payments and third-party calls"], ["Secrets", "Keys stored on the server side, never in the front-end"]]) + r"""<div class="box"><b>Never</b> put secret keys in front-end code. Use edge functions for payment secrets and private API keys; the public (anon) key is designed to be exposed but is only safe when RLS is correct.</div>""",
     3: r"""<h3>Publishing checklist</h3><ul><li>Test sign-up, login, logout, password reset and the main flow with two accounts.</li><li>Check mobile layout and speed.</li><li>Set page titles, descriptions and share images.</li><li>Connect a custom domain with HTTPS.</li><li>Add privacy policy and terms pages; add cookie notice if needed.</li></ul>""",
     5: r"""<h3>Credits and cost awareness</h3><ul><li>Each prompt uses credits; large rewrites cost more. Be specific, work in slices, and avoid 'rebuild everything'.</li><li>Use chat or plan mode for questions and planning without changing code (confirm current names).</li><li>Check plan limits for projects, users, storage and custom domains.</li></ul>""",
    }
    new = [
     ("intermediate", "Design to build: screens, components and visual edits", "Get the UI you want without wasting credits.", r"""
<ul><li><b>Start from structure:</b> list pages and sections first; ask for a layout with sample content.</li><li><b>Design system prompts:</b> define colours, fonts, spacing, border radius, button style, and ask for reusable components (Button, Card, Modal, Form).</li><li><b>Reference images:</b> upload a screenshot of a layout you like; ask to match the structure, not copy branding.</li><li><b>Visual edits:</b> use click-to-edit for text, colours and spacing to save prompts.</li><li><b>Responsive:</b> ask to check mobile, tablet and desktop; test in the preview's device modes.</li><li><b>Accessibility:</b> request labels, sufficient contrast, keyboard navigation and alt text.</li><li><b>Content:</b> provide real copy; avoid lorem ipsum.</li></ul>""" + tb(["Prompt", "Result"], [["Create a reusable PricingCard component with title, price, features and a CTA; show three plans", "A consistent component used three times"], ["Make the header sticky and collapse the menu into a hamburger on mobile; do not change other pages", "Targeted edit"], ["Use a 4-column grid on desktop, 2 on tablet, 1 on mobile for product cards", "Responsive layout"]]),
      ["Define the design system early.", "Use visual edits for small changes.", "Test on mobile every time."], "Write a design-system prompt (colours, type, components) and build a three-page site from it."),
     ("intermediate", "Authentication, roles and Row Level Security that actually protects data", "Set up logins and permissions correctly.", ill_flow(["Create tables", "Enable RLS on every table", "Write policies (who can read / write)", "Add login and roles", "Test with two users", "Review security scan"], "A safe data-access routine") + tb(["Scenario", "Policy idea"], [["Users see only their own records", "Allow select, insert, update where user_id = the logged-in user"], ["Public catalogue", "Allow select for everyone; insert and update only for admins"], ["Team data", "Allow access if the user is a member of the team (join table)"], ["Admin panel", "Store roles in a separate table; check role in the policy, not in the front-end"], ["Private files", "Storage policies by folder or owner"]]) + r"""
<ul><li><b>Roles:</b> keep roles in a protected table; never trust a role value sent from the browser.</li><li><b>Test attacks:</b> try to read another user's record by changing an ID in the URL or request.</li><li><b>Audit:</b> turn on logging and review the security scan results before launch.</li></ul>""",
      ["Enable RLS on every table.", "Roles live on the server side.", "Test by trying to break your own app."], "Write RLS policies in plain English for a booking app with patients, doctors and admins."),
     ("intermediate", "Payments, email, AI features and third-party APIs", "Add real-world features safely.", tb(["Feature", "How", "Safety"], [["Payments", "Hosted checkout (Razorpay or Stripe) via an edge function; webhook marks order as paid", "Never trust the browser; verify webhook signatures; store payment IDs"], ["Transactional email", "Provider API called from an edge function", "Rate limits; no secrets in front-end"], ["AI features (chat, summaries)", "Call a model API from an edge function with your key", "Limit usage per user; filter inputs; log costs"], ["Maps and location", "Maps API with restricted keys", "Restrict by domain; consent for location"], ["Analytics", "Events to an analytics tool", "Avoid personal data in events"], ["WhatsApp / SMS", "Provider API via edge function", "Opt-in, templates, DND rules"]]) + r"""
<p>For each integration, write the data flow: user action → front-end → edge function → provider → database → confirmation, and list what can fail.</p>""",
      ["Use edge functions for secrets.", "Verify webhooks and store IDs.", "Limit AI and email usage per user."], "Add a payment flow design (steps and failure cases) for a paid plan."),
     ("advanced", "Testing, quality and the security scan", "Ship fewer bugs.", SECURITY + tb(["Test type", "Examples"], [["Happy path", "Sign up, book, pay, confirm"], ["Edge cases", "Empty fields, long text, wrong dates, double clicks, back button"], ["Permissions", "User A tries to open User B's data"], ["Mobile and slow network", "Real device on 4G"], ["Regression", "Re-test earlier features after each change"]]) + r"""<p>Ask the AI to write a short test checklist and to explain each fix it makes. Keep a list of known issues.</p>""",
      ["Test happy path, edge cases and permissions.", "Do a security review before publishing.", "Keep known issues documented."], "Create a test checklist with 15 cases for your app and run it."),
     ("advanced", "GitHub, collaboration and moving to production", "Work with engineers and grow beyond the prototype.", r"""
<ul><li><b>GitHub sync:</b> connect a repository; the code stays in sync; engineers can review, branch and extend. Avoid editing the same files in two places at once.</li><li><b>Environments:</b> separate Supabase projects for development and production; do not test on live data.</li><li><b>Handoff package:</b> repository, README, environment variable names, database schema and RLS policy list, user flows, known risks and next steps.</li><li><b>When to rebuild:</b> if performance, compliance or complex logic needs exceed the generated code, plan a clean build with engineers using the prototype as a specification.</li><li><b>Maintenance:</b> update dependencies, monitor errors, rotate keys, review RLS after schema changes.</li></ul>""" + tb(["Stage", "Goal", "Exit criteria"], [["Prototype", "Learn", "5 users complete the main flow"], ["MVP", "Real use", "Auth, RLS, payments, monitoring, support process"], ["Scale", "Reliability", "Engineering ownership, testing, SLAs"]]),
      ["Sync to GitHub and keep environments separate.", "Prepare a handoff package.", "Plan a rebuild when needs outgrow the prototype."], "Prepare a handoff document for an app you built in Lovable."),
     ("advanced", "Playbook: from idea to launched MVP in two weeks", "Follow a time-boxed plan.", tb(["Day", "Focus", "Output"], [["1", "Problem, users, success metric; write the mini-PRD", "PRD and prompt pack"], ["2", "Layout and design system with sample data", "Clickable UI"], ["3 to 4", "Data model, auth and RLS", "Working login and data"], ["5 to 6", "Core flow end to end", "Main use case works"], ["7", "Payments or integrations (if needed)", "Test payments"], ["8", "Quality pass: test, security scan, mobile", "Bug list and fixes"], ["9", "Content, SEO basics, privacy and terms", "Ready pages"], ["10", "Beta with 10 users, collect feedback", "Insights"], ["11 to 12", "Fix top issues, add analytics", "Improved MVP"], ["13", "Publish with custom domain", "Live URL"], ["14", "Measure and decide: iterate, hand off or stop", "Decision memo"]]) + r"""
<div class="box">Define success first (for example 30 sign-ups and 10 completed bookings), so you know whether the MVP worked.</div>""",
      ["Time-box the MVP and define success first.", "Beta with real users before polishing.", "End with a decision: iterate, hand off or stop."], "Create your 14-day plan and run the first three days."),
    ]
    qa = [("What is Lovable and who is it for?", "An AI app builder that turns prompts into web apps with a live preview and Supabase backend. It suits PMs, founders and designers who want fast prototypes and MVPs."),
          ("What is Row Level Security and why is it important?", "Rules in the database that control which rows each user can read or change. Without correct RLS, users could access each other's data."),
          ("How do you handle secrets in a Lovable app?", "Keep private keys on the server side in edge functions and secrets; never in front-end code or prompts."),
          ("How do you write prompts that produce good results?", "State role, goal, screens, data, rules and style; work in small slices; use examples and screenshots; say what must stay unchanged."),
          ("How do you take payments safely?", "Use a hosted checkout, handle payment confirmation through a signed webhook on the server, store payment IDs, and never rely on the browser alone."),
          ("What do you test before publishing?", "Happy path, edge cases, permissions with two users, mobile on a slow network, and the security scan results."),
          ("When should you hand over to engineers?", "When there are real users, payments, sensitive data, scale or compliance needs, or logic beyond the generated code."),
          ("How do you manage credits and costs?", "Be specific, work in slices, use visual edits and chat mode for questions, and check plan limits.")]
    gl = [("RLS", "Row Level Security, database rules per user"), ("Policy", "A rule that allows or denies actions on rows"), ("Edge Function", "Small server-side function"), ("Anon key", "Public key for the front-end, safe only with RLS"), ("Service role key", "Powerful secret key; never expose"),
          ("Project knowledge", "Persistent instructions for the AI"), ("Visual edit", "Click-to-edit UI changes"), ("Webhook", "Message sent by a service when an event happens"), ("Staging", "Test environment")]
    cheat = [("Prompt formula", "Role, goal, screens, data, rules, style"), ("Security", "RLS on, secrets on server, test two users"), ("MVP plan", "14 days with beta and a decision"), ("Handoff", "Repo, README, schema, RLS list, risks")]
    return extend(C, deep, new, qa, gl, cheat, links=[("Supabase: Row Level Security guide", "https://supabase.com/docs/guides/database/postgres/row-level-security"), ("OWASP Top 10", "https://owasp.org/www-project-top-ten/")])
